//! Exact ST7701S serial-control/RGB pixel paths for 4B and3.16. Vendor bank
//! opcodes are not common DCS commands. 4B's complete9-bit words are decoded
//! at every actual TCA9554 write, not reconstructed from a final register value.
use std::sync::{Arc,Mutex};
use esp_periph::i2c::{I2cDevice,gt911::{Gt911,Gt911State}};
use esp_soc::{board::{BoardEdge,BoardModel,LcdRgbPins},pins::PinRoutes,devices::{i2c_bitbang::I2cBitBang,tca9554::{Tca9554,Tca9554State},pcf85063::{Pcf85063,Pcf85063State},axp2101::{Axp2101,Axp2101Power},es8311::Es8311,es7210::Es7210}};
const HZ:u64=240_000_000;
#[derive(Clone,Copy)]pub enum Variant{Lcd4b,Lcd316}
impl Variant{fn dimensions(self)->(u32,u32){match self{Self::Lcd4b=>(480,480),Self::Lcd316=>(320,820)}}fn i2c(self)->(u8,u8){match self{Self::Lcd4b=>(47,48),Self::Lcd316=>(15,7)}}fn backlight_active_low(self)->bool{matches!(self,Self::Lcd4b)}fn backlight(self)->u8{match self{Self::Lcd4b=>4,Self::Lcd316=>6}}fn data(self)->[u8;16]{match self{Self::Lcd4b=>[40,41,42,2,1,21,8,18,45,38,39,10,11,12,13,14],Self::Lcd316=>[21,5,45,48,47,14,13,12,11,10,9,17,46,3,8,18]}}fn signals(self)->[u8;4]{match self{Self::Lcd4b=>[9,46,3,17],Self::Lcd316=>[41,38,39,40]}}}
struct SerialState{reset_high:bool,clock:bool,shift:u16,bits:u8,page:u8,command:u8,args:[u8;5],count:usize,on:bool,sleeping:bool,madctl:u8,colmod:u8,inverted:bool,version:u64,resets:u64,words:u64}
impl Default for SerialState{fn default()->Self{Self{reset_high:false,clock:false,shift:0,bits:0,page:0,command:0,args:[0;5],count:0,on:false,sleeping:true,madctl:0,colmod:0x70,inverted:false,version:0,resets:0,words:0}}}
impl SerialState{
 fn reset(&mut self){self.page=0;self.command=0;self.count=0;self.on=false;self.sleeping=true;self.madctl=0;self.colmod=0x70;self.inverted=false;self.shift=0;self.bits=0;self.resets=self.resets.wrapping_add(1);self.version+=1;}
 fn word(&mut self,dc:bool,v:u8){self.words+=1;if !dc{self.command=v;self.count=0;if self.page==0{match v{1=>self.reset(),0x10=>self.sleeping=true,0x11=>self.sleeping=false,0x20=>self.inverted=false,0x21=>self.inverted=true,0x28=>self.on=false,0x29=>self.on=true,_=>{}}}}
 else if self.command==0xff{if self.count<5{self.args[self.count]=v;self.count+=1;}
 if self.count==5&&self.args[..4]==[0x77,1,0,0]{self.page=self.args[4];}}
 else{if self.page==0&&self.count==0{match self.command{0x36=>self.madctl=v,0x3a=>self.colmod=v&0x70,_=>{}}}self.count=self.count.saturating_add(1);}self.version+=1;}
 fn wire(&mut self,cs:Option<bool>,clock:Option<bool>,data:Option<bool>,reset:bool){if self.reset_high&&!reset{self.reset();}
 if self.reset_high!=reset{self.version+=1;}self.reset_high=reset;let high=clock==Some(true);if !reset||cs!=Some(false)||clock.is_none()||data.is_none(){self.bits=0;self.shift=0;}else if high&&!self.clock{self.shift=(self.shift<<1)|u16::from(data==Some(true));self.bits+=1;if self.bits==9{let w=self.shift;self.bits=0;self.shift=0;self.word(w&0x100!=0,w as u8);}}self.clock=high;}
 fn expander(&mut self,io:&Tca9554State){self.wire(io.driven(0),io.driven(2),io.driven(1),io.driven(7)==Some(true));}
}
struct ExpanderPort{inner:Tca9554,io:Arc<Mutex<Tca9554State>>,serial:Arc<Mutex<SerialState>>}
impl I2cDevice for ExpanderPort{fn start(&mut self,r:bool)->bool{self.inner.start(r)}fn write(&mut self,v:u8)->bool{let okay=self.inner.write(v);if okay{self.serial.lock().expect("ST7701 serial").expander(&self.io.lock().expect("4B expander"));}okay}fn read(&mut self)->u8{self.inner.read()}fn stop(&mut self){self.inner.stop();}}
struct TouchPort{inner:Gt911,io:Arc<Mutex<Tca9554State>>,address:Arc<Mutex<u8>>,at:u8}
impl I2cDevice for TouchPort{fn start(&mut self,r:bool)->bool{self.io.lock().expect("4B expander").driven(5)==Some(true)&&*self.address.lock().expect("4B strap")==self.at&&self.inner.start(r)}fn write(&mut self,v:u8)->bool{self.inner.write(v)}fn read(&mut self)->u8{self.inner.read()}}
pub struct WaveshareSerialRgb{variant:Variant,serial:Arc<Mutex<SerialState>>,io:Arc<Mutex<Tca9554State>>,touch:Arc<Mutex<Gt911State>>,address:Arc<Mutex<u8>>,rtc:Arc<Mutex<Pcf85063State>>,pmu:Arc<Mutex<Axp2101Power>>,i2c:I2cBitBang,attached:bool,cycle:u64,levels:[bool;2],edges:Vec<BoardEdge>,touch_high:bool,touch_falls:u64,frame:Vec<u16>,frame_epoch:u64,mapping:Option<[u8;16]>,frames:u64,version:u64,light:u32,gpio_light:u32,pwm:Option<u32>,card:bool}
impl WaveshareSerialRgb{
 pub fn new(variant:Variant)->Self{let(w,h)=variant.dimensions();Self{variant,serial:Default::default(),io:Default::default(),touch:Arc::new(Mutex::new(Gt911State::new(w as u16,h as u16,HZ/100))),address:Arc::new(Mutex::new(0x5d)),rtc:Arc::new(Mutex::new(Pcf85063State::new(HZ))),pmu:Default::default(),i2c:I2cBitBang::new(),attached:false,cycle:0,levels:[true;2],edges:Vec::new(),touch_high:false,touch_falls:0,frame:vec![0;w as usize*h as usize],frame_epoch:0,mapping:None,frames:0,version:0,light:0,gpio_light:0,pwm:None,card:false}}
 fn sync(&mut self){let light=self.pwm.unwrap_or(self.gpio_light);if light!=self.light{self.light=light;self.version+=1;}
 if matches!(self.variant,Variant::Lcd4b){let mut io=self.io.lock().expect("4B expander");let high=io.driven(5)==Some(true);let falls=io.falling_edges(5);if falls!=self.touch_falls{self.touch_falls=falls;*self.touch.lock().expect("4B touch")=Gt911State::new(480,480,HZ/100);}
 if high&&!self.touch_high{*self.address.lock().expect("4B strap")=if io.driven(6)==Some(false){0x5d}else{0x14};}self.touch_high=high;let mut t=self.touch.lock().expect("4B touch");t.powered=high;t.advance_to(self.cycle);io.set_inputs(1<<6,if !high||!t.ready{1<<6}else{0});}}
}
impl BoardModel for WaveshareSerialRgb{
 fn name(&self)->&'static str{match self.variant{Variant::Lcd4b=>"waveshare-s3-touch-lcd4b",Variant::Lcd316=>"waveshare-s3-lcd316"}}
 fn uses_gpio_routes(&self)->bool{true}
 fn gpio_waveform_at(&mut self,c:u64,r:PinRoutes<'_>){self.cycle=c;let[clk,hs,vs,de]=self.variant.signals();let pads=self.variant.data();let pins=LcdRgbPins{clock:if r.matrix_output(usize::from(clk),154){1<<clk}else{0},hsync:if r.matrix_output(usize::from(hs),151){1<<hs}else{0},vsync:if r.matrix_output(usize::from(vs),152){1<<vs}else{0},enable:if r.matrix_output(usize::from(de),150){1<<de}else{0},data:std::array::from_fn(|i|pads.iter().filter(|&&pin|r.matrix_output(usize::from(pin),133+i as u32)).fold(0,|v,&pin|v|(1<<pin))),width:16};self.lcd_rgb_pins(pins);self.gpio_light=if r.software_output(self.variant.backlight())==Some(!self.variant.backlight_active_low()){65535}else{0};if matches!(self.variant,Variant::Lcd316){self.serial.lock().expect("ST7701 serial").wire(r.software_output(0),r.software_output(2),r.software_output(1),r.software_output(16)==Some(true));}let(sda,scl)=self.variant.i2c();let clock=r.software_output(scl).unwrap_or(true);let data=self.i2c.drive(clock,r.software_output(sda).unwrap_or(true));for(i,(pin,high))in[(sda,data),(scl,clock)].into_iter().enumerate(){if high!=self.levels[i]{self.levels[i]=high;self.edges.push(BoardEdge{cycle:c,pin,level:high});}}self.sync();}
 fn uses_gpio_pwm(&self)->bool{true}
 fn gpio_pwm_at(&mut self,c:u64,p:&dyn Fn(u8)->Option<(f64,u32)>){self.cycle=c;self.pwm=p(self.variant.backlight()).map(|(_,d)|if self.variant.backlight_active_low(){65535-d.min(65535)}else{d.min(65535)});self.sync();}
 fn lcd_rgb_pins(&mut self,p:LcdRgbPins){let[clk,hs,vs,de]=self.variant.signals();let mut valid=p.width==16&&p.clock&(1<<clk)!=0&&p.hsync&(1<<hs)!=0&&p.vsync&(1<<vs)!=0&&p.enable&(1<<de)!=0;let mut map=[0;16];for(i,pad)in self.variant.data().into_iter().enumerate(){if let Some(bit)=(0..16).find(|b|p.data[*b]&(1<<pad)!=0){map[i]=bit as u8;}else{valid=false;}}let next=valid.then_some(map);if next!=self.mapping{self.mapping=next;self.version+=1;}}
 fn lcd_frame(&mut self,w:u32,h:u32,b:&[u8]){let Some(map)=self.mapping else{return;};let s=self.serial.lock().expect("ST7701 serial");if(w,h)!=self.variant.dimensions()||b.len()!=self.frame.len()*2||!s.reset_high{return;}for(d,src)in self.frame.iter_mut().zip(b.as_chunks::<2>().0){let v=u16::from_le_bytes(*src);*d=map.iter().enumerate().fold(0,|out,(bit,input)|out|(((v>>input)&1)<<bit));}self.frame_epoch=s.resets;self.frames+=1;self.version+=1;}
 fn i2c_devices(&mut self)->Vec<(u8,u8,Box<dyn I2cDevice>)>{if !self.attached{self.i2c.attach(0x51,Box::new(Pcf85063::new(self.rtc.clone())));if matches!(self.variant,Variant::Lcd4b){self.i2c.attach(0x20,Box::new(ExpanderPort{inner:Tca9554::new(self.io.clone()),io:self.io.clone(),serial:self.serial.clone()}));self.i2c.attach(0x34,Box::new(Axp2101::new(self.pmu.clone())));self.i2c.attach(0x18,Box::new(Es8311::new()));self.i2c.attach(0x40,Box::new(Es7210::new()));for at in[0x5d,0x14]{self.i2c.attach(at,Box::new(TouchPort{inner:Gt911::new(self.touch.clone()),io:self.io.clone(),address:self.address.clone(),at}));}}self.attached=true;}(0..2).flat_map(|b|self.i2c.controller_devices(Some(self.variant.i2c())).into_iter().map(move|(a,d)|(b,a,d))).collect()}
 fn advance_to(&mut self,c:u64){self.cycle=c;self.rtc.lock().expect("RGB RTC").advance_to(c);self.sync();}
 fn touch(&mut self,x:u16,y:u16,d:bool){if matches!(self.variant,Variant::Lcd4b){self.touch.lock().expect("4B touch").update(x,y,d);self.sync();}}
 fn take_edges(&mut self)->Vec<BoardEdge>{std::mem::take(&mut self.edges)}
 fn input_levels(&self)->Vec<(u8,bool)>{let(sda,scl)=self.variant.i2c();vec![(0,true),(sda,self.levels[0]),(scl,self.levels[1])]}
 fn named_pin(&self,n:&str)->Option<u8>{(n=="boot").then_some(0)}
 fn sd_card_slot(&self)->Option<([u8;6],bool)>{matches!(self.variant,Variant::Lcd316).then_some(([1,2,42,255,255,255],self.card))}
 fn set_sd_card_present(&mut self,p:bool){self.card=p;}
 fn display(&self)->Option<(u32,u32,Vec<u16>,u64)>{let(w,h)=self.variant.dimensions();let s=self.serial.lock().expect("ST7701 serial");let mut f=vec![0;self.frame.len()];if s.reset_high&&s.on&&!s.sleeping&&self.frame_epoch==s.resets&&self.mapping.is_some()&&self.light>0&&s.colmod==0x50&&s.madctl&!0x18==0{for y in 0..h as usize{let row=if s.madctl&0x10!=0{h as usize-1-y}else{y};for x in 0..w as usize{let mut v=self.frame[row*w as usize+x];if s.madctl&8!=0{v=(v&0x7e0)|(v>>11)|((v&31)<<11);}
 if s.inverted{v^=65535;}f[y*w as usize+x]=v;}}}let version=self.version.wrapping_add(s.version);Some((w,h,f,version))}
 fn display_version(&self)->u64{self.version.wrapping_add(self.serial.lock().expect("ST7701 serial").version)}
 fn display_frames(&self)->u64{self.frames}
 fn report(&self)->String{let s=self.serial.lock().expect("ST7701 serial");format!("{} {:?} ST7701S RGB565 with real nine-bit control, vendor banks, reset/sleep/on/COLMOD/MADCTL, GPIO/backlight gating (4B GPIO4 active-low per official BSP2.0.0, 3.16 GPIO6 active-high); serialWords={} frames={}. 4B TCA9554 EX0/1/2 LCD CS/data/clock EX7reset EX5GTreset EX6GTIRQ, 3.16 GPIO0/1/2 serial RST16. RTC control both, PMU/codecs4B, SDMMC1/2/42 only3.16. No QMI motion, analog PMU rail topology/latch/battery, calibrated PWM/glass, audioPCM, full factory or physical acceptance.",self.name(),self.variant.dimensions(),s.words,self.frames)}
}
#[cfg(test)]mod tests{use super::*;
 fn route(b:&mut WaveshareSerialRgb,cs:bool,clk:bool,data:bool,reset:bool){let mut g=esp_periph::Gpio::new();let mut m=esp_periph::RegRam::new();for(p,high)in[(0,cs),(2,clk),(1,data),(16,reset),(b.variant.backlight(),!b.variant.backlight_active_low())]{g.enable|=1<<p;if high{g.out|=1<<p;}m.write(4+4*u32::from(p),1<<12);}let signals=b.variant.signals();for(p,signal)in signals.into_iter().zip([154,151,152,150]).chain(b.variant.data().into_iter().enumerate().map(|(i,p)|(p,133+i as u32))){g.func_out_sel[p as usize]=signal;m.write(4+4*u32::from(p),1<<12);}b.gpio_waveform_at(b.cycle,esp_soc::pins::ChipPins::S3.routes(&g,&m));}
 fn write(d:&mut dyn I2cDevice,r:u8,v:u8){assert!(d.start(false));assert!(d.write(r));assert!(d.write(v));d.stop();}
 fn send(b:&mut WaveshareSerialRgb,ds:&mut[(u8,u8,Box<dyn I2cDevice>)],dc:bool,v:u8){let word=u16::from(v)|(u16::from(dc)<<8);for bit in(0..9).rev(){let data=word&(1<<bit)!=0;match b.variant{Variant::Lcd316=>{route(b,false,false,data,true);route(b,false,true,data,true);},Variant::Lcd4b=>{let d=ds.iter_mut().find(|(bus,a,_)|*bus==0&&*a==0x20).unwrap().2.as_mut();write(d,1,0xa0|(u8::from(data)<<1));write(d,1,0xa4|(u8::from(data)<<1));}}}match b.variant{Variant::Lcd316=>route(b,true,false,false,true),Variant::Lcd4b=>write(ds.iter_mut().find(|(bus,a,_)|*bus==0&&*a==0x20).unwrap().2.as_mut(),1,0xa1)}}
 #[test]fn independent_serial_transports_require_complete_words_rgb_pads_and_new_frame_after_reset(){for variant in[Variant::Lcd4b,Variant::Lcd316]{let mut b=WaveshareSerialRgb::new(variant);let mut ds=b.i2c_devices();if matches!(variant,Variant::Lcd4b){write(ds.iter_mut().find(|(bus,a,_)|*bus==0&&*a==0x20).unwrap().2.as_mut(),3,0x40);}route(&mut b,true,false,false,true);for c in[0x11,0x29]{send(&mut b,&mut ds,false,c);}send(&mut b,&mut ds,false,0x3a);send(&mut b,&mut ds,true,0x55);let[clk,hs,vs,de]=variant.signals();let p=LcdRgbPins{clock:1<<clk,hsync:1<<hs,vsync:1<<vs,enable:1<<de,width:16,data:variant.data().map(|p|1<<p)};b.lcd_rgb_pins(p);let(w,h)=variant.dimensions();let mut f=vec![0;w as usize*h as usize*2];f[..4].copy_from_slice(&[0,0xf8,0xe0,7]);b.lcd_frame(w,h,&f);assert_eq!(&b.display().unwrap().2[..2],&[0xf800,0x7e0]);let mut wrong=p;wrong.clock=1<<43;b.lcd_rgb_pins(wrong);b.lcd_frame(w,h,&f);assert_eq!(b.frames,1);b.lcd_rgb_pins(p);send(&mut b,&mut ds,false,0xff);for v in[0x77,1,0,0,0x11]{send(&mut b,&mut ds,true,v);}send(&mut b,&mut ds,false,0x10);assert!(!b.serial.lock().unwrap().sleeping,"vendor10 is not common sleep");send(&mut b,&mut ds,false,0xff);for v in[0x77,1,0,0,0]{send(&mut b,&mut ds,true,v);}send(&mut b,&mut ds,false,1);assert_eq!(b.display().unwrap().2[0],0);for c in[0x11,0x29]{send(&mut b,&mut ds,false,c);}send(&mut b,&mut ds,false,0x3a);send(&mut b,&mut ds,true,0x55);assert_eq!(b.display().unwrap().2[0],0,"fresh init must not resurrect stale RGB delivery");b.lcd_frame(w,h,&f);assert_eq!(b.display().unwrap().2[0],0xf800);}}
 #[test]fn four_b_backlight_duty_is_source_inverted_and_floating_is_off(){
  let mut b=WaveshareSerialRgb::new(Variant::Lcd4b);let mut g=esp_periph::Gpio::new();let mut m=esp_periph::RegRam::new();
  b.gpio_waveform_at(0,esp_soc::pins::ChipPins::S3.routes(&g,&m));assert_eq!(b.light,0);
  g.enable|=1<<4;m.write(4+4*4,1<<12);g.out|=1<<4;b.gpio_waveform_at(1,esp_soc::pins::ChipPins::S3.routes(&g,&m));assert_eq!(b.light,0);
  g.out&=!(1<<4);b.gpio_waveform_at(2,esp_soc::pins::ChipPins::S3.routes(&g,&m));assert_eq!(b.light,65535);
  b.gpio_pwm_at(3,&|p|(p==4).then_some((5000.,65535)));assert_eq!(b.light,0);
  b.gpio_pwm_at(4,&|p|(p==4).then_some((5000.,0)));assert_eq!(b.light,65535);
  b.gpio_pwm_at(5,&|p|(p==4).then_some((5000.,16384)));assert_eq!(b.light,49151);
  let mut c=WaveshareSerialRgb::new(Variant::Lcd316);c.gpio_pwm_at(1,&|p|(p==6).then_some((5000.,16384)));assert_eq!(c.light,16384);
 }
 #[test]fn four_b_gt_irq_is_expander_input_and_absent_on316(){let mut b=WaveshareSerialRgb::new(Variant::Lcd4b);let mut ds=b.i2c_devices();let d=ds.iter_mut().find(|(bus,a,_)|*bus==0&&*a==0x20).unwrap().2.as_mut();write(d,3,0x40);write(d,1,0xa0);b.advance_to(1);assert_eq!(*b.address.lock().unwrap(),0x14);b.touch(111,222,true);b.advance_to(HZ/100+2);write(d,0,0);assert!(d.start(true));assert_eq!(d.read()&(1<<6),0);assert!(b.sd_card_slot().is_none());let mut a=WaveshareSerialRgb::new(Variant::Lcd316);assert!(a.i2c_devices().iter().all(|(_,at,_)|!matches!(at,0x14|0x5d|0x34|0x20)));a.set_sd_card_present(true);assert_eq!(a.sd_card_slot(),Some(([1,2,42,255,255,255],true)));}
}
